// QuestStatusBar — the persistent, TRANSPARENT bottom HUD for quest screens
// (dreamscape, atlas, site views).
//
// It is a TRANSPARENT HUD — no background, no border, no top rule (Principle
// two): the essence total, deck sprite, Dreamcaller bust, and docked dreamsign
// strip sit DIRECTLY on the scene art, made legible by the `.hud-outline` glyph
// dilation (ported into quest-status-bar.css), not by a bar behind them.
// There is no menu-dots button — the menu lives in a top-left menu button on
// the screen.
//
// Everything press-reveals through the one shared engine (Tango's InfoCard /
// usePressReveal / PressPopover), so timing can't diverge:
//   - the essence value           → InfoCard 'text'
//   - the Dreamcaller bust (pops ABOVE the bar) → InfoCard 'hero'
//   - each docked dreamsign        → InfoCard 'object'
//   - >stackThreshold dreamsigns collapse into an overflow stack → a centered
//     viewer window (not a bottom sheet)
//
// Pass `stageRef` — the screen root (position:absolute inset:0 in the scaled
// frame); the press-reveal popovers portal into it so placement/clamping use
// stage coordinates.
//
// Ported from the Claude Design "Dreamtides Mobile" project
// (components/quest/QuestStatusBar.jsx / .d.ts). Two deliberate adaptations to
// Tango:
//   - The design source resolves the shared engine + RulesText from a global
//     DS bundle at render time; here it imports Tango's InfoCard engine
//     directly. Dreamsign / Dreamcaller ability text renders as plain body
//     text for now — RulesText's keyword highlighting lands with that
//     component (a later import); the InfoCard body slot already accepts it.
//   - Each bespoke press target wires `onPointerEnter`/`onPointerLeave` to
//     Tango's input-adaptive usePressReveal (hover reveals on a fine pointer,
//     press reveals on touch), exactly as InfoCard.PressInfo does, so the HUD
//     reveals on desktop as well as touch.
//
// The deck sprite is embedded as a data URI (faithfully copied from the source)
// — there is no separate asset to load.

import * as React from "react";
import type { CSSProperties, ReactElement } from "react";
import { createPortal } from "react-dom";
import { InfoCard } from "./InfoCard";
import type { AnchorRect } from "./InfoCard";
import { token } from "../primitives/tokens";
import "./quest-status-bar.css";

const { PressPopover, usePressReveal, anchorRect, PRESS_SCALE } = InfoCard;

/** The docked deck sprite, embedded so there is no separate asset to load. */
const DECK_SPRITE = "data:image/png;base64,";

/** The dreamsign object's own drop-shadow + violet glow (its material, not a
 * legibility overlay) — a faithfully-copied literal with no token equivalent. */
const DS_SHADOW =
  "drop-shadow(0 3px 6px rgba(0,0,0,0.55)) drop-shadow(0 0 13px rgba(147,51,234,0.32))";

/** One docked dreamsign (icon + name + optional rules ability). */
export interface QsbDreamsign {
  id: string | number;
  name: string;
  art: string;
  ability?: string;
}

/** The active Dreamcaller shown as a bust in the HUD. */
export interface QsbDreamcaller {
  name: string;
  epithet?: string;
  portrait?: string;
  wash?: string;
  ability?: string;
}

export interface QuestStatusBarProps {
  /** Ref to the screen root (position:absolute inset:0 in the scaled frame). Required. */
  stageRef: React.RefObject<HTMLElement | null>;
  /** Essence total shown in the HUD. */
  essence?: number;
  /** The dreamsigns to dock (≤ stackThreshold inline, more collapse to a stack + viewer). */
  dreamsigns?: QsbDreamsign[];
  /** Deck size (used in the deck button's aria-label). */
  deck?: number | string;
  dreamcaller?: QsbDreamcaller;
  /** Lift the essence cluster above the baseline (px). */
  elevation?: number;
  /** Independent elevation for the dreamsign strip (px). */
  signElevation?: number;
  portraitScale?: number;
  portraitSize?: number;
  signGap?: number;
  stackThreshold?: number;
}

/* a single bare, pressable dreamsign object — raises its detail card through the
   shared press-reveal engine (anchored over the object). */
function QsbSignObject({
  sign,
  size,
  stageRef,
  marginLeft = 0,
  z = 1,
}: {
  sign: QsbDreamsign;
  size: number;
  stageRef: React.RefObject<HTMLElement | null>;
  marginLeft?: number;
  z?: number;
}): ReactElement {
  const ref = React.useRef<HTMLSpanElement>(null);
  const { pressed, shown, begin, end, enter, leave } = usePressReveal();
  const [anchor, setAnchor] = React.useState<AnchorRect | null>(null);
  React.useLayoutEffect(() => {
    if (shown && stageRef.current && ref.current) {
      setAnchor(anchorRect(stageRef.current, ref.current));
    } else {
      setAnchor(null);
    }
  }, [shown, stageRef]);
  return (
    <span
      ref={ref}
      role="button"
      aria-label={sign.name}
      onPointerEnter={enter}
      onPointerDown={begin}
      onPointerUp={end}
      onPointerLeave={leave}
      onPointerCancel={end}
      style={{
        width: size,
        height: size,
        flex: "none",
        display: "block",
        marginLeft,
        position: "relative",
        zIndex: pressed ? 99 : z,
        cursor: "pointer",
        touchAction: "none",
        WebkitTapHighlightColor: "transparent",
        transform: pressed ? `scale(${String(PRESS_SCALE)})` : "scale(1)",
        transition: `transform ${token("--dur-fast")} ${token("--ease-out")}`,
      }}
    >
      <img
        src={sign.art}
        alt=""
        draggable={false}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "contain",
          display: "block",
          filter: DS_SHADOW,
          pointerEvents: "none",
          userSelect: "none",
        }}
      />
      {anchor &&
        stageRef.current &&
        createPortal(
          <PressPopover anchor={anchor}>
            <InfoCard
              variant="object"
              image={sign.art}
              imageFilter={DS_SHADOW}
              title={sign.name}
              body={sign.ability ? sign.ability : null}
            />
          </PressPopover>,
          stageRef.current,
        )}
    </span>
  );
}

/* OverflowStack — the >stackThreshold overlapping dreamsign stack. A press
   compresses it; a tap opens the viewer window. */
function QsbOverflowStack({
  signs,
  onOpenWindow,
}: {
  signs: QsbDreamsign[];
  onOpenWindow: () => void;
}): ReactElement {
  const size = 36;
  const { pressed, begin, end } = usePressReveal();
  const onUp = (): void => {
    end();
    onOpenWindow();
  };
  return (
    <button
      type="button"
      onPointerDown={begin}
      onPointerUp={onUp}
      onPointerLeave={end}
      onPointerCancel={end}
      aria-label={`View ${String(signs.length)} dreamsigns`}
      style={{
        display: "flex",
        alignItems: "center",
        padding: 0,
        border: "none",
        background: "none",
        cursor: "pointer",
        touchAction: "none",
        WebkitTapHighlightColor: "transparent",
        transform: pressed ? "scale(0.95)" : "scale(1)",
        transition: `transform ${token("--dur-fast")} ${token("--ease-out")}`,
      }}
    >
      {signs.map((s, i) => (
        <img
          key={s.id}
          src={s.art}
          alt=""
          draggable={false}
          style={{
            width: size,
            height: size,
            objectFit: "contain",
            display: "block",
            marginLeft: i ? -size * 0.46 : 0,
            filter: DS_SHADOW,
            pointerEvents: "none",
          }}
        />
      ))}
    </button>
  );
}

/* HUD strip: positioned just left of the deck button (measured live). */
function QsbDreamsignStrip({
  signs,
  stageRef,
  onOpenWindow,
  gap = 8,
  stackThreshold = 4,
  signElevation = 0,
}: {
  signs: QsbDreamsign[];
  stageRef: React.RefObject<HTMLElement | null>;
  onOpenWindow: () => void;
  gap?: number;
  stackThreshold?: number;
  signElevation?: number;
}): ReactElement | null {
  const [box, setBox] = React.useState<{ right: number; bottomY: number } | null>(
    null,
  );

  React.useLayoutEffect(() => {
    let raf = 0;
    const measure = (): void => {
      const stage = stageRef.current;
      const deck = stage?.querySelector('button[aria-label^="View deck"]');
      const sr = stage?.getBoundingClientRect();
      if (!stage || !deck || !sr || sr.width === 0 || deck.getBoundingClientRect().width === 0) {
        raf = requestAnimationFrame(measure);
        return;
      }
      const dr = deck.getBoundingClientRect();
      const k = stage.clientWidth / sr.width;
      setBox({
        right: stage.clientWidth - (dr.left - sr.left) * k + gap,
        bottomY: (dr.bottom - sr.top) * k - signElevation,
      });
    };
    measure();
    const stage = stageRef.current;
    const ro = stage ? new ResizeObserver(measure) : null;
    if (ro && stage) {
      ro.observe(stage);
    }
    window.addEventListener("resize", measure);
    return () => {
      cancelAnimationFrame(raf);
      if (ro) {
        ro.disconnect();
      }
      window.removeEventListener("resize", measure);
    };
  }, [stageRef, signs.length, gap, signElevation]);

  if (!signs.length || !box) {
    return null;
  }

  const SIGN = 36;
  const wrap: CSSProperties = {
    position: "absolute",
    right: box.right,
    top: box.bottomY - SIGN,
    display: "flex",
    alignItems: "flex-end",
    zIndex: 41,
    touchAction: "none",
  };

  if (signs.length <= stackThreshold) {
    return (
      <div style={{ ...wrap, gap: 2 }}>
        {signs.map((s) => (
          <QsbSignObject key={s.id} sign={s} size={SIGN} stageRef={stageRef} />
        ))}
      </div>
    );
  }

  return (
    <div style={wrap}>
      <QsbOverflowStack signs={signs} onOpenWindow={onOpenWindow} />
    </div>
  );
}

/* the viewer window for the overflow case — a grid of bare dreamsigns. This is
   the one centered solid window (not a bottom sheet). */
function QsbDreamsignWindow({
  signs,
  stageRef,
  onClose,
}: {
  signs: QsbDreamsign[];
  stageRef: React.RefObject<HTMLElement | null>;
  onClose: () => void;
}): ReactElement {
  return (
    <div
      onClick={onClose}
      style={{
        position: "absolute",
        inset: 0,
        zIndex: 70,
        display: "grid",
        placeItems: "center",
        padding: token("--gutter"),
        background: token("--scrim"),
        animation: `qsbCardIn ${token("--dur-fast")} ${token("--ease-out")} both`,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          position: "relative",
          width: "min(330px, 100%)",
          padding: "20px 20px 24px",
          background: token("--surface-glass-strong"),
          border: `1px solid ${token("--border-soft")}`,
          borderRadius: token("--radius-hero"),
          boxShadow: token("--shadow-lg"),
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            marginBottom: 16,
          }}
        >
          <h2 style={{ margin: 0, font: `600 21px/1 ${token("--font-title")}`, color: token("--text-primary") }}>
            Dreamsigns
          </h2>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            style={{
              width: 34,
              height: 34,
              borderRadius: token("--radius-control"),
              display: "grid",
              placeItems: "center",
              color: token("--text-secondary"),
              background: "rgba(255,255,255,0.05)",
              border: `1px solid ${token("--border-soft")}`,
              fontSize: 18,
              cursor: "pointer",
            }}
          >
            <i className="bxf bx-x" aria-hidden="true" />
          </button>
        </div>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(4, 1fr)",
            gap: 14,
            justifyItems: "center",
          }}
        >
          {signs.map((s) => (
            <QsbSignObject key={s.id} sign={s} size={60} stageRef={stageRef} />
          ))}
        </div>
      </div>
    </div>
  );
}

/* QsbDreamcallerBust — the Dreamcaller portrait button. Owns its own
   press-reveal (mirroring QsbSignObject): hover reveals on a fine pointer,
   press reveals on touch, and it portals its own 'hero' InfoCard. */
function QsbDreamcallerBust({
  dreamcaller,
  stageRef,
}: {
  dreamcaller: Partial<QsbDreamcaller>;
  stageRef: React.RefObject<HTMLElement | null>;
}): ReactElement {
  const ref = React.useRef<HTMLButtonElement>(null);
  const { pressed, shown, begin, end, enter, leave } = usePressReveal();
  const [anchor, setAnchor] = React.useState<AnchorRect | null>(null);
  React.useLayoutEffect(() => {
    if (shown && stageRef.current && ref.current) {
      setAnchor(anchorRect(stageRef.current, ref.current));
    } else {
      setAnchor(null);
    }
  }, [shown, stageRef]);
  return (
    <button
      ref={ref}
      type="button"
      aria-label="Dreamcaller"
      onPointerEnter={enter}
      onPointerDown={begin}
      onPointerUp={end}
      onPointerLeave={leave}
      onPointerCancel={end}
      style={{
        // width/height are set by quest-status-bar.css (var(--qsb-dc-size),
        // !important) so the bust tracks the portraitSize prop; kept here only
        // as a same-value fallback for when that stylesheet has not loaded.
        width: 66,
        height: 66,
        flex: "none",
        borderRadius: token("--radius-control"),
        overflow: "hidden",
        border: `2px solid ${token("--border-accent")}`,
        boxShadow: token("--glow-accent-soft"),
        // Faithfully-copied bespoke gradient literal: the first stop #2a2140 has
        // NO exact token equivalent (--primitive-plum-500 is #2a2040, off by one digit),
        // so it stays a literal rather than silently shifting the design color.
        background: `radial-gradient(circle at 50% 30%, #2a2140, ${token("--primitive-void-700")})`,
        padding: 0,
        cursor: "pointer",
        touchAction: "none",
        WebkitTapHighlightColor: "transparent",
        transform: pressed ? `scale(${String(PRESS_SCALE)})` : "scale(1)",
        transition: `transform ${token("--dur-fast")} ${token("--ease-out")}`,
      }}
    >
      {dreamcaller.portrait && (
        <img
          src={dreamcaller.portrait}
          alt={dreamcaller.name}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
            objectPosition: "50% 10%",
            transform: "scale(1.55)",
            transformOrigin: "50% 0%",
          }}
        />
      )}
      {anchor &&
        stageRef.current &&
        createPortal(
          <PressPopover anchor={anchor}>
            <InfoCard
              variant="hero"
              image={dreamcaller.portrait}
              imagePos="50% 6%"
              wash={dreamcaller.wash}
              title={`${dreamcaller.name ?? ""}, ${dreamcaller.epithet ?? ""}`}
              body={dreamcaller.ability ? dreamcaller.ability : null}
            />
          </PressPopover>,
          stageRef.current,
        )}
    </button>
  );
}

/* QsbEssence — the essence total. Owns its own press-reveal (mirroring
   QsbSignObject) and portals its own 'text' InfoCard, so hover reveals on
   desktop and press reveals on touch. Rendered as the sole <span> child of the
   HUD's column div, matching the DOM shape quest-status-bar.css targets. */
function QsbEssence({
  essence = 0,
  stageRef,
}: {
  essence?: number;
  stageRef: React.RefObject<HTMLElement | null>;
}): ReactElement {
  const ref = React.useRef<HTMLSpanElement>(null);
  const { pressed, shown, begin, end, enter, leave } = usePressReveal();
  const [anchor, setAnchor] = React.useState<AnchorRect | null>(null);
  React.useLayoutEffect(() => {
    if (shown && stageRef.current && ref.current) {
      setAnchor(anchorRect(stageRef.current, ref.current));
    } else {
      setAnchor(null);
    }
  }, [shown, stageRef]);
  return (
    <span
      ref={ref}
      role="button"
      aria-label="Essence Total"
      onPointerEnter={enter}
      onPointerDown={begin}
      onPointerUp={end}
      onPointerLeave={leave}
      onPointerCancel={end}
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 0,
        font: `800 22px/1 ${token("--font-ui")}`,
        fontVariantNumeric: "tabular-nums",
        color: token("--text-primary"),
        cursor: "pointer",
        touchAction: "none",
        WebkitTapHighlightColor: "transparent",
        transformOrigin: "left center",
        transform: pressed ? `scale(${String(PRESS_SCALE)})` : "scale(1)",
        transition: `transform ${token("--dur-fast")} ${token("--ease-out")}`,
      }}
    >
      {essence}
      <i
        className="bxf bx-crypto"
        aria-hidden="true"
        style={{ color: token("--essence"), fontSize: 20 }}
      />
      {anchor &&
        stageRef.current &&
        createPortal(
          <PressPopover anchor={anchor}>
            <InfoCard
              variant="text"
              title="Essence Total"
              body="A currency you use during quests to modify your deck."
            />
          </PressPopover>,
          stageRef.current,
        )}
    </span>
  );
}

/* QsbHudBar — the bottom HUD row (Dreamcaller bust · essence total · deck
   sprite). The aria-labels + DOM shape match what quest-status-bar.css and the
   press-reveal logic target. */
function QsbHudBar({
  essence = 0,
  deck = 0,
  dreamcaller = {},
  stageRef,
  style = {},
}: {
  essence?: number;
  deck?: number | string;
  dreamcaller?: Partial<QsbDreamcaller>;
  stageRef: React.RefObject<HTMLElement | null>;
  style?: CSSProperties;
}): ReactElement {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 10,
        height: token("--hud-h"),
        padding: "0 12px",
        paddingBottom: "env(safe-area-inset-bottom, 0px)",
        ...style,
      }}
    >
      <QsbDreamcallerBust dreamcaller={dreamcaller} stageRef={stageRef} />
      <div style={{ display: "flex", flexDirection: "column", gap: 4, marginRight: "auto" }}>
        <QsbEssence essence={essence} stageRef={stageRef} />
      </div>
      <button
        type="button"
        className="qsbDeck"
        aria-label={`View deck — ${String(deck)} cards`}
        style={{
          height: 66,
          flex: "none",
          padding: 0,
          border: "none",
          background: "transparent",
          display: "grid",
          placeItems: "center",
          cursor: "pointer",
          WebkitTapHighlightColor: "transparent",
        }}
      >
        <img
          src={DECK_SPRITE}
          alt=""
          draggable={false}
          style={{
            height: 63,
            width: "auto",
            display: "block",
            filter:
              "drop-shadow(0 2px 5px rgba(0,0,0,0.6)) drop-shadow(0 0 12px rgba(147,51,234,0.3))",
          }}
        />
      </button>
    </div>
  );
}

/**
 * QuestStatusBar — the persistent, TRANSPARENT bottom HUD for quest screens.
 * Essence total, deck sprite, Dreamcaller bust, and a
 * docked dreamsign strip sit directly on scene art (legible via `.hud-outline`),
 * all press-revealing through the shared InfoCard engine. No menu-dots button.
 */
export function QuestStatusBar({
  stageRef,
  essence,
  dreamsigns = [],
  deck = 0,
  dreamcaller,
  elevation = 0,
  signElevation = 0,
  portraitScale = 2.9,
  portraitSize = 66,
  signGap = 8,
  stackThreshold = 4,
}: QuestStatusBarProps): ReactElement {
  const [signWindow, setSignWindow] = React.useState(false);
  const dc: Partial<QsbDreamcaller> = dreamcaller ?? {};

  // The essence value and Dreamcaller bust each own their press-reveal
  // (QsbEssence / QsbDreamcallerBust) with per-element onPointerEnter/Leave, so
  // hover reveals on a fine pointer and press reveals on touch. A container-
  // level pointerenter can't drive this — native pointerenter does not refire
  // when the pointer moves between children of the same ancestor.
  return (
    <div
      className="qsb"
      style={
        {
          "--qsb-elev": `${String(elevation)}px`,
          "--qsb-dc-scale": portraitScale,
          "--qsb-dc-size": `${String(portraitSize)}px`,
        } as CSSProperties
      }
    >
      <div
        className="qsbHud hud-outline"
        style={{ position: "absolute", left: 0, right: 0, bottom: 0, zIndex: 40 }}
      >
        <QsbHudBar
          essence={essence}
          deck={deck}
          dreamcaller={dc}
          stageRef={stageRef}
          style={{
            height: `calc(${token("--hud-h")} + ${token("--safe-bottom")})`,
            paddingBottom: token("--safe-bottom"),
          }}
        />
      </div>

      <QsbDreamsignStrip
        signs={dreamsigns}
        stageRef={stageRef}
        gap={signGap}
        stackThreshold={stackThreshold}
        signElevation={signElevation}
        onOpenWindow={() => setSignWindow(true)}
      />
      {signWindow && (
        <QsbDreamsignWindow
          signs={dreamsigns}
          stageRef={stageRef}
          onClose={() => setSignWindow(false)}
        />
      )}
    </div>
  );
}
